import pandas as pd

def clean(df):
    df = df.drop_duplicates().reset_index(drop=True)
    df['Category'] = df['Category'].str.strip()
    df['Category'] = df['Category'].replace({
        'Furnture': 'Furniture',
        'Accesories': 'Accessories'
    })
    return df

def answer(df):
    return df['Category'].value_counts().to_dict()
